  response_key: "R_ROW_" + i,
  variable_name: "sintoma_" + (i + 1),
  label: "Item " + (i + 1),
  label_html: "<p>Item <em>" + (i + 1) + "</em></p>",
  helper_html: null,
  footer_html: "",
